/* Table Body */
.mica-table td {
    padding: 18px 12px;
    border: 1px solid #e5e5e5;
    font-weight: 400 !important;
    color: #404040;
    text-align: left !important;
    vertical-align: middle;
}
.btn-icon-slide {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    padding: 0 !important;
    color: #981C20 !important;
    font-size: inherit;
    font-weight: 600;
    cursor: pointer;
    text-decoration: none !important;
    box-shadow: none !important;
    outline: none !important;
    appearance: none !important;
    -webkit-appearance: none !important;
}

.btn-icon-slide .btn-text {
    position: relative;
    color: #981C20;
    text-decoration: none;
}

.btn-icon-slide .btn-text::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: -5px;
    width: 0;
    height: 2px;
    background: #981C20;
    transition: width 0.3s ease;
}

.btn-icon-slide:hover .btn-text::after {
    width: 100%;
}

.btn-icon-slide .btn-arrow {
    font-family: 'Material Symbols Outlined';
    font-size: 22px;
    line-height: 1;
    color: #981C20;
    transition: transform 0.3s ease;
}

.btn-icon-slide:hover .btn-arrow {
    transform: translateX(6px);
}

.btn-icon-slide:hover,
.btn-icon-slide:focus,
.btn-icon-slide:active {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    outline: none !important;
}

.btn-icon-slide::before,
.btn-icon-slide::after {
    box-shadow: none !important;
}

/* Responsive Table */
.mica-table-wrapper {
    width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    border: 1px solid #e5e5e5;
    border-radius: 8px;
    box-sizing: border-box;
}

.mica-table {
    width: 100%;
    min-width: 750px;
    margin: 0 !important;
    border-collapse: collapse;
    border-spacing: 0;
    border: 0;
    text-align: left !important;
    font-size: 18px;
    color: #404040;
    background-color: #fff;
}

/* Table Header */
.mica-table thead tr {
