}

/* Center View Information heading and buttons */
.mica-table th:last-child,
.mica-table td:last-child {
    text-align: center !important;
    vertical-align: middle;
}

.mica-table td:last-child .btn-icon-slide {
    display: inline-flex;
    justify-content: center;
    align-items: center;
    margin: 0 auto;
}

/* Keep other columns left-aligned */
.mica-table th:not(:last-child),
.mica-table td:not(:last-child) {
    text-align: left !important;
}
 

 
 

     

         
         
             
